 const { chromium } = require('playwright');
 const fs = require('fs');
 const path = require('path');

 async function testAccessibility() {
   const browser = await chromium.launch();
   const page = await browser.newPage();

   const htmlPath = path.join(__dirname, 'index.html');
   const htmlContent = fs.readFileSync(htmlPath, 'utf-8');

   await page.setContent(htmlContent, { waitUntil: 'load' });

   // Wait for DOMContentLoaded and component rendering
   await page.waitForLoadState('networkidle');
   await page.evaluate(() => {
     return new Promise(resolve => {
       if (document.readyState === 'complete') {
         resolve();
       } else {
         document.addEventListener('DOMContentLoaded', resolve);
       }
     });
   });

   // Give JS time to render the component
   await page.waitForTimeout(100);

   await page.addScriptTag({ path: '/tmp/axe.min.js' });

   const results = await page.evaluate(async () => {
     return await window.axe.run();
   });

   await browser.close();

   // Separate WCAG violations from best-practice
   const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
   const bp = results.violations.filter(v => v.tags.includes('best-practice'));

   const report = {
     wcag: wcag.map(v => ({
       id: v.id,
       impact: v.impact,
       description: v.description,
       nodes: v.nodes.length,
       targets: v.nodes.map(n => n.target)
     })),
     bp: bp.map(v => ({
       id: v.id,
       description: v.description,
       nodes: v.nodes.length,
       targets: v.nodes.map(n => n.target)
     }))
   };

   console.log(JSON.stringify(report, null, 2));

   process.exit(wcag.length > 0 ? 1 : 0);
 }

 testAccessibility().catch(err => {
   console.error(err);
   process.exit(1);
 });

